        "自動化興起，ZX1000i+是您的首選",
        "ZX1000i+ 系列配備強固的機芯，專為工業上大量列印需求而設計，適用於生產鏈中的任何環節。",
        "免費的軟體 GoLabel II 支援資料庫列印，提供資料處理的靈活性。",
        "齊全的選配以及標準的傳輸介面方便整合於各種運用環境中。",
        "全金屬的列印機體",
