        "256MB 的記憶體內建 5 種向量字可列印英數字以外的不同字型豐富您列印的內容。",
        "多元傳輸介面",
        "ZX1000i+標準配置 USB、RS232、LAN，以及 USB Host。加上選配的 WiFi 以及藍芽模組，不論有線或是無限的作業環境都有適切的界面連接。",
        "前飾板配置額外 2 個 USB Host 可搭配外接鍵盤、掃描器、或是 USB disk 可支援單機操作或是擴充記憶體使用。",
        "多樣解析度的選擇",
        "ZX1000i+ 系列擁有不同的列印解析度供選擇，從基本的 203 dpi(8 dots/mm) 到中階的 300 dpi(12 dots/mm) 以及細緻的 600 dpi(24 dots/mm) 解析度應有盡有。針對列印品質的不同需求都可從中獲得滿足。",
        "支援大量的列印工作",
        "ZX1000i+ 系列最多可安裝 450 米長的碳帶以及八吋直徑的紙捲，在大印量列印工作中可節省頻繁更換耗材的的時間。",
        "碳帶以及紙捲容易安裝的特點讓耗材更換不再是負擔。",
        "內捲和外捲碳帶自動調整的功能讓您靈活地使用手邊擁有的碳帶。",
        "維修容易",
        "備品像是印表頭以及滾輪等，在設計時考量減少維修的負擔，所以在設計上以較少拆裝程序為導向。",
