        "隨著產品微型化趨勢加速，標籤尺寸日益縮小，PX940 能以高精度從邊到邊準確列印小尺寸標籤。",
        "PX940 適用於運輸與物流、製藥與醫療照護、貨運與配送中心、工業製造、",
        "汽車零件供應商及其他需遵循法規，並要求高精度與無誤列印的應用場景。",
        "PX940 提供兩種版本：一為內建驗證器版本，另一為無驗證器版本。",
        "兩者皆支援標準功能，如低功耗藍牙（Bluetooth® LE）、可搭配 Print Set MC 使用，",
        "以及智慧列印功能讓使用者無需主機電腦即可設定標籤機與列印作業。",
